import{_ as t,C as s,o as r,c as i,j as o,a as d,E as n,a5 as c}from"./chunks/framework.B1qnvv14.js";const v=JSON.parse('{"title":"App para o telefone (Android)","description":"","frontmatter":{},"headers":[],"relativePath":"app.md","filePath":"app.md","lastUpdated":1793391883000}'),p={name:"app.md"};function l(m,a,u,h,g,k){const e=s("CopyOrDownloadAsMarkdownButtons");return r(),i("div",null,[a[0]||(a[0]=o("h1",{id:"app-para-o-telefone-android",tabindex:"-1"},[d("App para o telefone (Android) "),o("a",{class:"header-anchor",href:"#app-para-o-telefone-android","aria-label":'Permalink to "App para o telefone (Android)"'},"​")],-1)),n(e),a[1]||(a[1]=c(`<p>Um app leve para acompanhar o monitor do automacli pelo celular, <strong>só quando o telefone está no mesmo Wi‑Fi do PC</strong>: widget na tela inicial com os containers no ar, notificação quando um serviço falha e, no Android 16+ (One UI 8+), os containers em execução no Now Bar como Live Update. Nada passa pela nuvem; fora da rede do PC o app não usa rede nem bateria.</p><h2 id="instalar" tabindex="-1">Instalar <a class="header-anchor" href="#instalar" aria-label="Permalink to &quot;Instalar&quot;">​</a></h2><ol><li>Baixe o APK: <a href="https://github.com/Gustavo210/automacli-releases/releases/tag/app-latest" target="_blank" rel="noreferrer">app-latest em automacli-releases</a> (link fixo, atualizado a cada merge na <code>main</code> que toque em <code>android/</code>). Também fica como artefato de cada execução do workflow <em>App Android</em>.</li><li>Instale pelo navegador do telefone (permita instalar de fontes desconhecidas para o navegador).</li><li>No PC, com o monitor rodando como serviço (<code>automacli monitor setup</code>), pareie:</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">automacli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> monitor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pair</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s24</span></span></code></pre></div><ol start="4"><li>Aponte a câmera do telefone para o QR code. O app abre, guarda a URL e o token (só de leitura) e já conecta. Sem QR code, preencha a URL (<code>http://&lt;ip-do-pc&gt;:7777</code>) e o token à mão na tela de configurações.</li></ol><h2 id="o-que-ele-faz" tabindex="-1">O que ele faz <a class="header-anchor" href="#o-que-ele-faz" aria-label="Permalink to &quot;O que ele faz&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Recurso</th><th>Como funciona</th></tr></thead><tbody><tr><td><strong>Tela principal</strong></td><td>O mesmo formato do painel do PC: disco real, aparente e economia do reflink no topo, busca, e um card por task com slot (<code>UP S35</code> quando no ar), disco real e aparente, arquivos não commitados, estado do PR, chips de review e checks, gráfico de CPU e memória ao vivo (a cada 5 s com a tela aberta) e os botões <strong>PR</strong>, <strong>Links</strong>, <strong>Recursos</strong> e <strong>Remover</strong> (só quando o ciclo de vida permite; o motivo aparece embaixo).</td></tr><tr><td><strong>Widget</strong></td><td>Três tamanhos: pequeno (containers, stacks, disco real e aparente), médio (mais duas tasks) e grande (até sete tasks com a situação: mergeada, pronta para merge, checks, review; atalho <code>#PR</code> que abre o GitHub e botão <em>recursos</em> que abre o app na task). Cores do tema do aparelho. Fora da rede mostra o último estado com a idade.</td></tr><tr><td><strong>Modo apresentação</strong></td><td>Botão <em>Apresentar</em>: tela preta pura para o AMOLED, brilho reduzido, sempre ligada, retrato ou paisagem. O conteúdo é o gráfico de CPU e memória de cada stack no ar ocupando a tela (lado a lado em paisagem, em faixas em retrato), com os valores atuais em números grandes, lido a cada 5 s; as tasks paradas viram só uma contagem. Contra burn‑in, o conteúdo desloca alguns pixels a cada minuto e o relógio muda de canto; sem animações, só recompõe quando chega evento. Toque para sair.</td></tr><tr><td><strong>Notificação fixa</strong></td><td>Exigência do Android para a conexão ficar aberta, e útil: &quot;48 containers em 2 stacks&quot; ou &quot;Fora da rede do PC&quot;.</td></tr><tr><td><strong>Now Bar / Live Update</strong></td><td>No Android 16+ a notificação fixa pede para ser promovida: aparece no Now Bar do One UI com uma barra verde (no ar) e vermelha (com problema). Precisa permitir &quot;notificações ao vivo&quot; para o app nos ajustes do Android. Pode ser desligado no app.</td></tr><tr><td><strong>Alertas</strong></td><td>Container em restart ou parado com erro, serviço compartilhado parado, disco btrfs baixo, serviço morto por falta de memória, falha na atualização do repo base. A notificação some sozinha quando o monitor avisa que resolveu.</td></tr><tr><td><strong>Catch‑up</strong></td><td>Ao voltar para a rede, o app pede ao monitor o que perdeu desde o último evento; alertas de quando você estava fora chegam nessa hora.</td></tr><tr><td><strong>Recursos</strong></td><td>Memória e CPU por stack (soma do <code>docker stats</code>) na lista, e por serviço ao tocar na task; disco real em btrfs por task e no total, com o que o reflink poupa.</td></tr><tr><td><strong>Links</strong></td><td>Ao tocar na task, todas as URLs dela abrem no navegador do telefone. Nomes como <code>*.devtest</code> só resolvem se o DNS do Wi‑Fi do telefone apontar para o PC (o <code>dnsmasq</code> compartilhado atende na porta 53).</td></tr><tr><td><strong>Ações</strong></td><td>Parar ou iniciar a stack de uma task e subir ou parar os serviços compartilhados, com confirmação. Exige aparelho pareado com escopo <code>control</code> (padrão de <code>automacli monitor pair</code>); com <code>--read-only</code> os botões respondem que o aparelho só lê.</td></tr><tr><td><strong>Atualização</strong></td><td>Em Configurações, <em>Verificar atualização</em> consulta a release <code>app-latest</code> no GitHub (única coisa que usa internet), baixa o APK e abre o instalador. Só atualiza por cima se o APK do CI estiver assinado com a mesma chave (<code>setup-signing.sh</code>).</td></tr></tbody></table><h2 id="como-ele-se-conecta" tabindex="-1">Como ele se conecta <a class="header-anchor" href="#como-ele-se-conecta" aria-label="Permalink to &quot;Como ele se conecta&quot;">​</a></h2><p>O app observa o Wi‑Fi. Em qualquer rede nova, tenta o monitor por 3 segundos; se responde, abre o fluxo de eventos (<a href="./monitor#eventos"><code>/api/events</code></a>) e fica nele; se não responde, é outra rede, e ele tenta de novo a cada minuto sem alarde. O tráfego é amarrado à interface Wi‑Fi, então funciona mesmo quando o Wi‑Fi não tem internet e o Android preferiria o 4G. O token é só de leitura (<a href="./monitor#acesso-do-telefone">Acesso do telefone</a>).</p><h2 id="aparelhos-pareados" tabindex="-1">Aparelhos pareados <a class="header-anchor" href="#aparelhos-pareados" aria-label="Permalink to &quot;Aparelhos pareados&quot;">​</a></h2><p><code>automacli monitor pair --list</code> mostra cada aparelho com escopo, último acesso, IP e quantas conexões de eventos estão abertas agora. <code>--disable &lt;nome&gt;</code> corta o acesso na hora (as conexões caem e o token é recusado) sem apagar o pareamento; <code>--enable</code> reativa; <code>--revoke</code> apaga. Detalhes em <a href="./monitor#acesso-do-telefone">Monitor → Acesso do telefone</a>.</p><h2 id="samsung-one-ui" tabindex="-1">Samsung (One UI) <a class="header-anchor" href="#samsung-one-ui" aria-label="Permalink to &quot;Samsung (One UI)&quot;">​</a></h2><ul><li>Em <strong>Ajustes &gt; Apps &gt; automacli &gt; Bateria</strong>, escolha <em>Sem restrições</em> e tire o app da lista de <em>apps que dormem</em>; senão o One UI encerra a conexão depois de alguns dias.</li><li>O app usa dois caminhos para o Now Bar ao mesmo tempo: o Live Update do Android 16 e o que os apps parceiros do Samsung usam (extras <code>android.ongoingActivityNoti.*</code> com o <code>meta-data</code> <code>com.samsung.android.support.ongoing_activity</code>, como o Samsung Health). Em Config há ainda o toggle <em>Estilo nativo Samsung</em>, que troca o Live Update pelo estilo oculto <code>OngoingActivityStyle</code> do Gravador de Voz; nenhum dos dois é API pública, então o diagnóstico mostra o que o aparelho aceitou.</li><li>Para o Now Bar, dois ajustes: <strong>Ajustes &gt; Notificações &gt; Configurações avançadas &gt; Notificações ao vivo</strong> e permita o automacli; e, como o Now Bar só mostra apps parceiros por padrão, ligue <strong>Opções do desenvolvedor &gt; Notificações ao vivo para todos os apps</strong>. O app tem um diagnóstico em Config (permissão, elegibilidade e se a notificação foi promovida).</li><li>Depois de reiniciar o telefone, o app volta sozinho se estava ligado.</li></ul><h2 id="compilar" tabindex="-1">Compilar <a class="header-anchor" href="#compilar" aria-label="Permalink to &quot;Compilar&quot;">​</a></h2><p>O projeto fica em <code>android/</code> (Kotlin, Jetpack Compose, Glance, OkHttp; sem Firebase). Fora do pacote npm. Com o SDK do Android instalado:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> android</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :app:assembleDebug</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # app/build/outputs/apk/debug/app-debug.apk</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :app:assembleRelease</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # minificado (~4 MB); sem chave, assinado com a de debug</span></span></code></pre></div><p>O workflow <code>.github/workflows/android.yml</code> compila em todo push ou PR que toque <code>android/</code> e, na <code>main</code>, publica a release rolante <code>app-latest</code>. Para o APK do CI atualizar por cima do instalado, a chave precisa ser sempre a mesma: rode uma vez <code>android/scripts/setup-signing.sh</code>, que cria <code>~/.config/automacli/app-release.jks</code> e grava os secrets <code>ANDROID_KEYSTORE_BASE64</code>, <code>ANDROID_KEYSTORE_PASSWORD</code>, <code>ANDROID_KEY_ALIAS</code> e <code>ANDROID_KEY_PASSWORD</code> no repositório. Guarde o <code>.jks</code> e o <code>.env</code> ao lado: perdê-los obriga a trocar de chave e reinstalar.</p>`,17))])}const b=t(p,[["render",l]]);export{v as __pageData,b as default};
